#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long m;
    cin >> n >> m;
    vector<vector<long long>> flights(m, vector<long long>(3));
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < 3; j++) {
            cin >> flights[i][j];
        }
    }
    long long src;
    long long dst;
    long long k;
    cin >> src >> dst >> k;

    const long long INF = 1000000000000000000LL;
    vector<long long> dist(n + 1, INF);
    dist[src] = 0;
    for (long long round = 0; round <= k; round++) {
        vector<long long> next = dist;
        for (const vector<long long>& f : flights) {
            if (dist[f[0]] < INF && dist[f[0]] + f[2] < next[f[1]]) next[f[1]] = dist[f[0]] + f[2];
        }
        if (next == dist) break;
        dist = next;
    }
    cout << (dist[dst] < INF ? dist[dst] : -1) << "\n";

    return 0;
}

