import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long m = Long.parseLong(next());
        long[][] flights = new long[(int) m][3];
        for (int i = 0; i < flights.length; i++) {
            for (int j = 0; j < flights[i].length; j++) {
                flights[i][j] = Long.parseLong(next());
            }
        }
        long src = Long.parseLong(next());
        long dst = Long.parseLong(next());
        long k = Long.parseLong(next());

        long INF = 1000000000000000000L;
        long[] dist = new long[(int) n + 1];
        Arrays.fill(dist, INF);
        dist[(int) src] = 0;
        for (long round = 0; round <= k; round++) {
            long[] next = dist.clone();
            for (long[] f : flights) {
                if (dist[(int) f[0]] < INF && dist[(int) f[0]] + f[2] < next[(int) f[1]]) next[(int) f[1]] = dist[(int) f[0]] + f[2];
            }
            if (Arrays.equals(next, dist)) break;
            dist = next;
        }
        System.out.println(dist[(int) dst] < INF ? dist[(int) dst] : -1);
    }
}
